// Inline object typing (Good for small objects)
function printLocation(pt: { x: number; y: number }) {
  console.log(`The coordinates are X: ${pt.x}, Y: ${pt.y}`);
}

// Using a Type Alias (Better for reuse)
type User = {
  id: number;
  name: string;
};

const currentUser: User = {
  id: 1,
  name: "Alice"
};

